detectionRule.ruleCode:
rule Windows_Trojan_Chrysalis {
  meta:
    author = "Elastic Security Labs"
    actor = "Lotus Blossom APT"
  strings:
    $fnv1a = { C7 ?? C5 9D 1C 81 }
    $murmur1 = { 69 ?? 51 2D 9E CC }
    $murmur2 = { 69 ?? 93 35 87 1B }
  condition:
    uint16(0) == 0x5A4D and all of them
}
